"""Modern app generated by Rewind.

This file is the same for every generated app: it reads spec.json (screens,
data model, rules) and seed.json (the data seen in the legacy recording)
and serves the app with Flask and SQLite. The spec was filled in by Muse
Spark and validated by Rewind; there is no generated code here.

Run:  uv run python app.py [--port 5001] [--reset] [--db data/app.db]
Login: user from the recording; password from APP_ADMIN_PASSWORD, or a
random one printed on the first start.
"""

import argparse
import json
import os
import re
import secrets
import sqlite3
import unicodedata
from contextlib import closing
from datetime import date
from decimal import Decimal, InvalidOperation
from functools import wraps
from pathlib import Path

from flask import Flask, abort, flash, g, get_flashed_messages, redirect, render_template, request, session, url_for
from werkzeug.security import check_password_hash, generate_password_hash

import expr

HERE = Path(__file__).resolve().parent


# ---------- Spec helpers ----------


def norm(text) -> str:
    text = unicodedata.normalize("NFKD", str(text or ""))
    return " ".join("".join(c for c in text if not unicodedata.combining(c)).upper().split())


class Spec:
    def __init__(self, data: dict):
        self.data = data
        self.entities = {e["name"]: e for e in data["entities"]}
        self.screens = {s["id"]: s for s in data["screens"]}

    def field(self, entity: str, name: str) -> dict:
        return next(f for f in self.entities[entity]["fields"] if f["name"] == name)

    def stored(self, entity: str) -> list[dict]:
        return [f for f in self.entities[entity]["fields"] if f["type"] != "serial"]

    def host(self, screen_id: str) -> str:
        """The page a screen is shown on (itself, or the search page it was merged into)."""
        return self.screens[screen_id].get("embedded_in") or screen_id


# ---------- Values: display text <-> storage ----------


def parse_value(spec: Spec, entity: str, field: dict, text, db=None):
    """Turn what a user typed (or the legacy screen showed) into the stored value.
    Returns (value, error)."""
    text = "" if text is None else str(text).strip()
    if text == "":
        return None, None
    kind = field["type"]
    if kind == "money":
        try:
            amount = Decimal(re.sub(r"[^\d.\-]", "", text))
        except InvalidOperation:
            return None, "Monto inválido"
        if amount != amount.quantize(Decimal("0.01")):
            return None, "Monto inválido"
        return int(amount * 100), None
    if kind == "date":
        for pattern, order in ((r"^(\d{4})-(\d{2})-(\d{2})$", (0, 1, 2)), (r"^(\d{2})/(\d{2})/(\d{4})$", (2, 1, 0))):
            if m := re.match(pattern, text):
                y, mo, d = (int(m.group(i + 1)) for i in order)
                try:
                    return date(y, mo, d).isoformat(), None
                except ValueError:
                    break
        return None, "Fecha inválida"
    if kind == "enum":
        match = next((v for v in field["enum_values"] if norm(v) == norm(text)), None)
        return (match, None) if match else (None, "Valor inválido")
    if kind == "ref":
        if text.isdigit():
            return int(text), None
        target = spec.entities[field["ref"]]
        for row in db.execute(f"SELECT id, {target['display']} AS d FROM {target['name']}"):
            if norm(row["d"]) == norm(text):
                return row["id"], None
        return None, "Registro no encontrado"
    return text, None


def show_value(spec: Spec, field: dict, value, row=None, db=None) -> str:
    kind = field["type"]
    if kind == "serial":
        return f"{field['serial_prefix']}{row['id']:0{field.get('serial_digits', 4)}d}" if row else ""
    if value is None or value == "":
        return ""
    if kind == "money":
        return f"{spec.data.get('currency', '')}{value / 100:,.2f}"
    if kind == "date":
        y, m, d = value.split("-")
        return f"{d}/{m}/{y}"
    if kind == "ref":
        target = spec.entities[field["ref"]]
        found = db.execute(f"SELECT {target['display']} FROM {target['name']} WHERE id = ?", (value,)).fetchone()
        return found[0] if found else ""
    return str(value)


# ---------- Database ----------

SQL_TYPES = {"text": "TEXT", "money": "INTEGER", "date": "TEXT", "enum": "TEXT", "ref": "INTEGER"}


def connect(path: Path) -> sqlite3.Connection:
    db = sqlite3.connect(path)
    db.row_factory = sqlite3.Row
    db.execute("PRAGMA foreign_keys = ON")
    return db


def init_db(spec: Spec, path: Path, seed: dict, reset: bool = False) -> str | None:
    """Create the tables and load the seed. Returns a new admin password if one was generated."""
    if reset and path.exists():
        path.unlink()
    fresh = not path.exists()
    path.parent.mkdir(parents=True, exist_ok=True)
    with closing(connect(path)) as db, db:
        if not fresh:
            return None
        db.execute("CREATE TABLE users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password_hash TEXT)")
        for entity in spec.entities.values():
            columns = [f"{f['name']} {SQL_TYPES[f['type']]}" for f in spec.stored(entity["name"])]
            db.execute(f"CREATE TABLE {entity['name']} (id INTEGER PRIMARY KEY, {', '.join(columns)})")
        # Seed entities in an order where referenced records exist first.
        pending = list(seed)
        while pending:
            name = next(n for n in pending if all(
                f["ref"] not in pending or f["ref"] == n for f in spec.stored(n) if f["type"] == "ref"))
            pending.remove(name)
            for record in seed[name]:
                values = {}
                for f in spec.stored(name):
                    value, error = parse_value(spec, name, f, record.get(f["name"]), db)
                    if error:
                        raise ValueError(f"seed {name}.{f['name']} = {record.get(f['name'])!r}: {error}")
                    values[f["name"]] = value
                db.execute(
                    f"INSERT INTO {name} ({', '.join(values)}) VALUES ({', '.join('?' * len(values))})",
                    list(values.values()),
                )
        password = os.environ.get("APP_ADMIN_PASSWORD") or secrets.token_urlsafe(9)
        for user in spec.data.get("users", ["ADMIN"]):
            db.execute("INSERT INTO users (username, password_hash) VALUES (?, ?)",
                       (norm(user), generate_password_hash(password)))
        return None if os.environ.get("APP_ADMIN_PASSWORD") else password


# ---------- App ----------


def create_app(spec_data: dict, db_path: Path) -> Flask:
    spec = Spec(spec_data)
    app = Flask(__name__, template_folder=str(HERE / "templates"), static_folder=str(HERE / "static"))
    app.secret_key = os.environ.get("APP_SECRET_KEY") or secrets.token_hex(32)

    def db() -> sqlite3.Connection:
        if "db" not in g:
            g.db = connect(db_path)
        return g.db

    @app.teardown_appcontext
    def close_db(_exc):
        if (conn := g.pop("db", None)) is not None:
            conn.close()

    def login_required(view):
        @wraps(view)
        def wrapper(*args, **kwargs):
            if "user" not in session:
                return redirect(url_for("login"))
            return view(*args, **kwargs)
        return wrapper

    @app.context_processor
    def helpers():
        return {"spec": spec, "show": lambda f, v, row=None: show_value(spec, f, v, row, db()), "norm": norm}

    def login_screen() -> dict:
        return next(s for s in spec.screens.values() if s["kind"] == "login")

    @app.route("/")
    def index():
        return redirect(url_for("page", screen_id=spec.data["home"]) if "user" in session else url_for("login"))

    @app.route("/login", methods=["GET", "POST"])
    def login():
        screen = login_screen()
        errors, values = {}, {}
        if request.method == "POST":
            values = {f["name"]: request.form.get(f["name"], "") for f in screen["fields"]}
            errors = validate(screen, values, {})
            if not errors:
                user = db().execute("SELECT * FROM users WHERE username = ?", (norm(values["username"]),)).fetchone()
                if user and check_password_hash(user["password_hash"], values["password"]):
                    session.clear()
                    session["user"] = user["username"]
                    return redirect(url_for("page", screen_id=spec.data["home"]))
                errors = {"_": "Usuario o clave incorrectos"}
        return render_template("login.html", screen=screen, errors=errors, values=values)

    @app.route("/logout")
    def logout():
        session.clear()
        return redirect(url_for("login"))

    # ----- validation and records -----

    def validate(screen: dict, raw: dict, scope: dict) -> dict:
        """Run the screen's validations. Returns {field name: legacy-style error text}."""
        errors = {}
        for v in screen.get("validations", []):
            value = raw.get(v["field"])
            failed = False
            if v["check"] == "required":
                failed = value in (None, "")
            elif value not in (None, ""):
                own = scope.get(screen.get("entity"), {}).get(v["field"])
                if v["check"] == "positive":
                    failed = own is not None and own <= 0
                elif v["check"] == "not_above":
                    failed = own is not None and own > expr.evaluate(v["other"], scope)
            if failed and v["field"] not in errors:
                errors[v["field"]] = f"ERROR {v['code']}: {v['message']}"
        return errors

    def read_form(screen: dict, entity: str) -> tuple[dict, dict, dict]:
        """(raw text, parsed values, type errors) for the screen's form fields."""
        raw = {f["name"]: request.form.get(f"f_{f['name']}", "") for f in screen["fields"]}
        values, errors = {}, {}
        for f in screen["fields"]:
            value, error = parse_value(spec, entity, spec.field(entity, f["name"]), raw[f["name"]], db())
            values[f["name"]] = value
            if error and raw[f["name"]]:
                errors[f["name"]] = error
        return raw, values, errors

    def insert(entity: str, values: dict) -> int:
        cur = db().execute(
            f"INSERT INTO {entity} ({', '.join(values)}) VALUES ({', '.join('?' * len(values))})", list(values.values())
        )
        return cur.lastrowid

    def record(entity: str, record_id) -> sqlite3.Row | None:
        return db().execute(f"SELECT * FROM {entity} WHERE id = ?", (record_id,)).fetchone()

    def rows(screen: dict, filters: dict | None = None) -> list[sqlite3.Row]:
        entity = spec.entities[screen["entity"]]
        where, params = [], []
        for f in screen.get("filters", []):
            value = (filters or {}).get(f["name"])
            if not value:
                continue
            column = f["field"]
            if f["op"] == "contains":
                where.append(f"{column} LIKE ?")
                params.append(f"%{value}%")
            elif f["op"] == "eq":
                where.append(f"{column} = ?")
                params.append(value)
            else:
                where.append(f"{column} {'>=' if f['op'] == 'from' else '<='} ?")
                params.append(value)
        sql = f"SELECT * FROM {entity['name']}"
        if where:
            sql += " WHERE " + " AND ".join(where)
        order = "id DESC" if screen["kind"] == "create" else f"{entity['display']}"
        return db().execute(sql + f" ORDER BY {order}", params).fetchall()

    def cell(screen: dict, column: dict, row) -> str:
        base, _, sub = column["field"].partition(".")
        field = spec.field(screen["entity"], base)
        if sub:
            target = record(field["ref"], row[base]) if row[base] else None
            return show_value(spec, spec.field(field["ref"], sub), target[sub], target, db()) if target else ""
        return show_value(spec, field, row[base] if field["type"] != "serial" else None, row, db())

    def options(entity: str, field_name: str) -> list[tuple[str, str]]:
        field = spec.field(entity, field_name)
        if field["type"] == "enum":
            return [(v, v) for v in field["enum_values"]]
        if field["type"] == "ref":
            target = spec.entities[field["ref"]]
            found = db().execute(f"SELECT id, {target['display']} AS d FROM {target['name']} ORDER BY d")
            return [(str(r["id"]), r["d"]) for r in found]
        return []

    def defaults(screen: dict) -> dict:
        out = {}
        for f in screen["fields"]:
            if f.get("default") == "today":
                out[f["name"]] = date.today().isoformat()
            elif f.get("default"):
                out[f["name"]] = f["default"]
        return out

    # ----- transaction context (used alone or inside its search page) -----

    def transaction_context(screen: dict, parent_id=None, lookup=None) -> dict:
        parent = None
        if parent_id:
            parent = record(screen["parent"], parent_id)
        elif lookup and screen.get("parent_lookup"):
            parent = db().execute(
                f"SELECT * FROM {screen['parent']} WHERE {screen['parent_lookup']} = ?", (lookup.strip(),)
            ).fetchone()
        return {"screen": screen, "parent": parent, "values": defaults(screen), "errors": {}, "lookup": lookup or ""}

    def search_context(screen: dict, args) -> dict:
        filters = {f["name"]: args.get(f["name"], "") for f in screen.get("filters", [])}
        query = {}
        for f in screen.get("filters", []):
            value = filters[f["name"]]
            if f["input"] == "date" and value:
                value, _ = parse_value(spec, screen["entity"], {"type": "date"}, value)
            query[f["name"]] = value
        # Like the legacy screen, the results stay empty until a search runs (or a record is open).
        searched = any(f["name"] in args for f in screen.get("filters", [])) or args.get("sel")
        return {"screen": screen, "filters": filters, "rows": rows(screen, query) if searched else [],
                "selected": args.get("sel", "")}

    def panel_for(screen: dict) -> dict | None:
        """The transaction screen merged into this search page, if any."""
        return next((s for s in spec.screens.values() if s.get("embedded_in") == screen["id"]), None)

    def render_page(screen_id: str, **extra):
        screen = spec.screens[screen_id]
        context = {"screen": screen, "errors": {}, "values": defaults(screen) if screen["kind"] != "search" else {}}
        if screen["kind"] == "create":
            context["rows"] = rows(screen)
        if screen["kind"] == "search":
            context |= search_context(screen, request.args)
            embedded = panel_for(screen)
            if embedded and request.args.get("panel") == embedded["id"] and context["selected"]:
                context["panel"] = transaction_context(embedded, parent_id=context["selected"])
        if screen["kind"] == "transaction":
            context |= transaction_context(screen, request.args.get("parent"), request.args.get("lookup"))
        context |= extra
        return render_template("page.html", cell=cell, options=options, **context)

    # ----- pages -----

    @app.route("/p/<screen_id>", methods=["GET", "POST"])
    @login_required
    def page(screen_id):
        screen = spec.screens.get(screen_id)
        if not screen or screen["kind"] == "login":
            abort(404)
        if request.method == "GET":
            if screen.get("embedded_in"):
                args = {"panel": screen_id, "sel": request.args.get("parent", "")}
                return redirect(url_for("page", screen_id=screen["embedded_in"], **args))
            return render_page(screen_id)
        if screen["kind"] == "create":
            return save_create(screen)
        if screen["kind"] == "transaction":
            return save_transaction(screen)
        abort(405)

    def success(screen: dict, **goto_args):
        flash(json.dumps({"text": screen["success"]["message"], "style": screen.get("success_style", "dialog")}))
        target = screen["success"].get("goto") or screen["id"]
        return redirect(url_for("page", screen_id=spec.host(target), **goto_args))

    def save_create(screen: dict):
        entity = screen["entity"]
        raw, values, errors = read_form(screen, entity)
        errors = validate(screen, raw, {entity: values}) | errors
        if errors:
            return render_page(screen["id"], values=raw, errors=errors)
        insert(entity, values)
        db().commit()
        return success(screen)

    def save_transaction(screen: dict):
        parent_id = request.form.get("parent")
        parent = record(screen["parent"], parent_id) if parent_id else None
        if not parent:
            abort(400)
        entity = screen["entity"]
        raw, values, errors = read_form(screen, entity)
        scope = {screen["parent"]: dict(parent), entity: values}
        errors = validate(screen, raw, scope) | errors
        if errors:
            context = transaction_context(screen, parent_id=parent_id) | {"values": raw, "errors": errors}
            if screen.get("embedded_in"):
                return render_page(screen["embedded_in"], panel=context, selected=parent_id)
            return render_page(screen["id"], **context)
        link = next(f["name"] for f in spec.stored(entity) if f["type"] == "ref" and f["ref"] == screen["parent"])
        insert(entity, values | {link: parent["id"]})
        updated = dict(parent)
        for effect in screen.get("effects", []):
            name = effect["target"].split(".", 1)[1]
            scope[screen["parent"]] = updated
            if effect.get("expr"):
                updated[name] = expr.evaluate(effect["expr"], scope)
            else:
                updated[name] = next(
                    (c["value"] for c in effect["cases"] if expr.evaluate(c["when"], scope)), effect.get("default")
                )
        sets = [n for n in updated if n != "id" and updated[n] != parent[n]]
        if sets:
            db().execute(
                f"UPDATE {screen['parent']} SET {', '.join(f'{n} = ?' for n in sets)} WHERE id = ?",
                [updated[n] for n in sets] + [parent["id"]],
            )
        db().commit()
        goto_args = {}
        target = screen["success"].get("goto")
        if screen["success"].get("with_parent") and target:
            display = spec.entities[screen["parent"]]["display"]
            goto = spec.screens[spec.host(target)]
            for f in goto.get("filters", []):
                if f["field"] == display:
                    goto_args[f["name"]] = updated[display]
            goto_args["sel"] = parent["id"]
        return success(screen, **goto_args)

    @app.context_processor
    def messages():
        return {"messages": [json.loads(m) for m in get_flashed_messages()]}

    return app


def main() -> None:
    parser = argparse.ArgumentParser(description="Modern app generated by Rewind")
    parser.add_argument("--port", type=int, default=5001)
    parser.add_argument("--reset", action="store_true", help="start again from the data seen in the recording")
    parser.add_argument("--db", type=Path, default=HERE / "data" / "app.db")
    args = parser.parse_args()

    spec_data = json.loads((HERE / "spec.json").read_text(encoding="utf-8"))
    seed = json.loads((HERE / "seed.json").read_text(encoding="utf-8"))
    password = init_db(Spec(spec_data), args.db, seed, args.reset)
    if password:
        print(f"Users: {', '.join(spec_data.get('users', ['ADMIN']))}  password: {password}")
        print("(set APP_ADMIN_PASSWORD to choose it; shown only on the first start)")
    create_app(spec_data, args.db).run(host="127.0.0.1", port=args.port)


if __name__ == "__main__":
    main()
